{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Vismodegib has an absolute oral bioavailability of 31.8% in humans, above the 20% threshold, despite a complex polar structure with a pyridyl group; this high-transfer analogue supports high F for the query's pyridyl/phenyl basic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Pethidine (meperidine) has an absolute oral bioavailability of 0.63 in healthy volunteers, showing that a basic piperidine-containing drug with first-pass metabolism can still achieve high F; this directly supports the query's basic piperidine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Disopyramide, which shares the pyridyl/phenyl and basic amine features of the query, has an absolute bioavailability of 73% after oral dosing, strongly supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Methadone has an absolute oral bioavailability of 0.85 in healthy volunteers; its lipophilic basic amine and diphenyl-like structure are relevant to the query and support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Atazanavir has an oral bioavailability of 60-68% in humans, demonstrating that even larger, more complex molecules with multiple polar groups can achieve high F; this supports the high prediction despite lower structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Encainide has an absolute oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold, and its basic amine/piperidine-like structure supports high F for the query, albeit with interindividual variability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to F >= 20%: multiple structurally related basic amines with pyridyl/phenyl motifs show absolute oral bioavailability from about 30% to 90%. The query's high ionization is not disqualifying, as several analogues are also ionizable basic amines with high F.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "First-pass metabolism and transporter-mediated efflux are not experimentally characterized for the query.",
    "The high basic pKa and complete ionization at pH 7.4 may affect permeability, but no direct permeability data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

